draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();

  // clouds
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.cos(t), H/2 - 50*Math.sin(t), 20 + 10*Math.sin(2*t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 100*Math.cos(t), H/2 + 50*Math.sin(t), 20 + 10*Math.cos(2*t), 0, 2*Math.PI);
  ctx.fill();

  // tree
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H);
  ctx.lineTo(W/2, H - 100 - 20*Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H - 120 - 20*Math.sin(t), 20 + 10*Math.cos(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 20*Math.cos(t), H - 100 - 20*Math.sin(t), 10 + 5*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20*Math.cos(t), H - 100 - 20*Math.sin(t), 10 + 5*Math.cos(t), 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
